from rendu import Point
p=Point(12)
p.h('Prévention primaire : cibler le risque sans promettre de modifier toute morphologie')
p.p('Une voûte plantaire qui se développe chez l’enfant ne doit pas être traitée comme une maladie à prévenir systématiquement. Le consensus BSCOS ne retrouve pas de preuve que des orthèses prophylactiques préviennent douleur ou incapacité à long terme, ni qu’elles modifient le développement de l’arche ; expliquer ce point évite un traitement sans bénéfice démontré.', 'pa82-plat-europe-prevention')
p.p('Le chapitre pédiatrique suisse de 2017 décrit la fréquence élevée du pied plat dans les premières années et son évolution avec la croissance. La prévention utile consiste ici à reconnaître douleur, rigidité, asymétrie ou signes généraux, plutôt qu’à imposer une forme de pied adulte à tout enfant.', ['p82-plat-physio','p82-plat-examen','pa82-plat-europe-imagerie'])
p.h('Prévention secondaire : repérer tôt ce qui change la trajectoire')
p.p('Chez la personne diabétique sans ulcère, IWGDF 2023 recommande un dépistage annuel de la perte de sensibilité protectrice et de l’artériopathie : monofilament de 10 g ou diapason de 128 Hz selon les moyens, interrogatoire sur la claudication et palpation des pouls. La présence de neuropathie ou d’artériopathie identifie un pied à risque nécessitant une évaluation plus approfondie.', 'pa82-pied-depistage')
p.p('Apprendre l’inspection quotidienne de tout le pied, y compris les espaces interdigitaux. Cette surveillance vise à repérer une lésion cutanée ; devant chaleur, rougeur ou gonflement d’un pied neuropathe, envisager aussi Charcot et engager sa filière de protection, même si la peau reste intacte.', ['pa82-pied-prevention','pa82-charcot-r1','pa82-charcot-r5'])
p.p('La source HUG 2023 encourage le repérage de la scoliose lors du suivi de l’enfant : observer les asymétries puis rechercher la gibbosité en flexion antérieure. Une mesure anormale au scoliomètre guide l’exploration ; un examen normal ne justifie pas de radiographies répétées sans indication.', ['p82-scoliose-hug','pa82-scoliose-normalite'])
p.p('Pour les genoux, surveiller l’évolution et adresser les asymétries ou progressions ainsi que les valeurs incompatibles avec l’âge selon la publication suisse de 2014. Pour l’XLH, la publication suisse de 2024 souligne l’intérêt d’un traitement précoce pour atténuer les manifestations ; rechercher le mécanisme phosphaté devant des déformations progressives évite de s’en tenir à une correction orthopédique isolée.', ['pa82-genou-orientation','p82-xlh-clinique','p82-xlh-mecanisme-bilan'])
p.h('Prévention tertiaire : préserver la fonction après la première complication')
p.p('Après fracture du radius, évaluer le risque de chute et la santé osseuse et orienter vers une filière de prévention des fractures ou des chutes selon le contexte. Cette recommandation européenne complète l’attention portée par les HUG à l’ostéoporose du sujet âgé dans le mécanisme de fracture.', ['pa82-radius-prevention','p82-radius'])
p.p('Après rémission d’un Charcot, organiser chaussures et orthèses adaptées à la déformation résiduelle ; reprendre la charge progressivement et surveiller la réapparition des signes inflammatoires. La protection du pied se poursuit au-delà de la disparition du gonflement initial.', ['p82-charcot','pa82-charcot-remise-charge'])
p.p('Dans l’XLH, préparer le relais entre pédiatrie et soins adultes, maintenir le suivi spécialisé et intégrer soutien psychologique et social. Prévenir la rupture de soins est une action concrète face à une maladie dont les manifestations osseuses, dentaires et fonctionnelles persistent au-delà de la croissance.', ['pa82-xlh-transition','pa82-xlh-social','p82-xlh-clinique'])
p.sauver()
p=Point(13)
p.p('Devant une déformation traumatique, recherchez d’abord une ouverture, une menace cutanée et une atteinte neurovasculaire ; la perfusion ne se résume pas au temps de recoloration.', ['p82-radius','pa82-radius-ischemie'])
p.p('Protégez immédiatement le pied diabétique neuropathe chaud et gonflé suspect de Charcot, puis poursuivez le bilan même lorsque les premières radiographies sont normales.', ['pa82-charcot-r5','pa82-charcot-r8'])
p.p('Chez l’enfant, distinguez une déformation souple et indolore d’une douleur, d’une rigidité ou d’une progression asymétrique qui impose une autre démarche.', ['p82-plat-examen','pa82-genou-orientation'])
p.p('Ne confondez pas rotation du tronc au scoliomètre et angle de Cobb sur une radiographie du rachis entier debout.', ['p82-scoliose-clinique','p82-scoliose-radio'])
p.p('Interprétez la phosphatémie selon l’âge et recherchez la fuite rénale lorsqu’une déformation rachitique évoque l’XLH.', ['pa82-xlh-phosphate-age','p82-xlh-mecanisme-bilan'])
p.p('Pour le paracétamol, vérifiez poids, forme, âge, fonction rénale et hépatique ainsi que les autres médicaments, et ne transposez jamais l’intervalle adulte à l’enfant.', 'aips82-dafalgan-5')
p.sauver()
p=Point(14)
p.tableau(['Question d’examen', 'Réponse', 'Raison'], [
 [('Un poignet déformé conserve une recoloration normale : la lésion artérielle est-elle exclue ?','pa82-radius-ischemie'),('Non ; rechercher pouls, saignement persistant et hématome expansif, puis réévaluer après réalignement.','pa82-radius-ischemie'),('Recoloration et signal Doppler ne suffisent pas à exclure une atteinte vasculaire ; la persistance de signes forts impose une exploration immédiate.','pa82-radius-ischemie')],
 [('Un pied diabétique neuropathe chaud a des radiographies normales : peut-on attendre sans protection ?','pa82-charcot-r8'),('Non ; immobiliser et décharger pendant le bilan, puis demander une IRM si la suspicion persiste.',['pa82-charcot-r5','pa82-charcot-r8']),('Le Charcot actif peut précéder les anomalies radiographiques ; la protection précoce vise à limiter les lésions.',['p82-charcot','pa82-charcot-r5'])],
 [('Une CRP normale élimine-t-elle le Charcot sur peau intacte ?','pa82-charcot-r10'),('Non ; les marqueurs sanguins ne servent pas à affirmer ou exclure cette affection dans ce cadre.','pa82-charcot-r10'),('L’interprétation repose sur clinique et imagerie ; un bilan biologique rassurant ne ferme pas le diagnostic.',['pa82-charcot-r10','pa82-charcot-r8'])],
 [('Faut-il prescrire des semelles pour faire apparaître une voûte chez tout enfant au pied plat ?','pa82-plat-europe-prevention'),('Non si le pied est souple, indolore et fonctionnel ; informer et observer.',['p82-plat-examen','pa82-plat-europe-definition']),('Les orthèses prophylactiques n’ont pas de preuve de modification du développement de la voûte ni de prévention à long terme de douleur ou incapacité.','pa82-plat-europe-prevention')],
 [('Un angle de cinq degrés au scoliomètre est-il un Cobb de cinq degrés ?','p82-scoliose-clinique'),('Non ; il mesure la rotation du tronc et peut justifier l’imagerie selon le contexte suisse.','p82-scoliose-clinique'),('Le Cobb mesure une courbure radiographique sur les vertèbres limites ; les deux angles ne sont pas interchangeables.','p82-scoliose-radio')],
 [('Une grande avulsion du maillet implique-t-elle toujours une opération ?','pa82-maillet-os-congruent'),('Non ; une articulation congruente sans subluxation peut relever d’une attelle et d’un contrôle de profil sous attelle.','pa82-maillet-os-congruent'),('La congruence et la stabilité comptent ; la taille du fragment seule ne suffit pas.','pa82-maillet-os-congruent')],
 [('Peut-on immobiliser aussi l’interphalangienne proximale d’un maillet pour davantage de sécurité ?','pa82-maillet-pip'),('Il faut éviter cette immobilisation dans le traitement décrit.','pa82-maillet-pip'),('Elle expose à une rétraction en flexion de l’articulation proximale.','pa82-maillet-pip')],
 [('Une phosphatémie dans l’intervalle adulte est-elle toujours rassurante chez l’enfant ?','pa82-xlh-phosphate-age'),('Non ; utiliser l’intervalle correspondant à l’âge et le contexte du bilan.','pa82-xlh-phosphate-age'),('Les valeurs attendues sont plus élevées à plusieurs âges pédiatriques ; l’XLH associe hypophosphatémie et fuite rénale.',['pa82-xlh-phosphate-age','p82-xlh-mecanisme-bilan'])],
 [('Le score de rachitisme suffit-il pour affirmer une XLH ?','pa82-xlh-imagerie'),('Non ; il quantifie l’atteinte radiographique et doit être associé au bilan causal.',['pa82-xlh-imagerie','p82-xlh-mecanisme-bilan']),('Le mécanisme PHEX–FGF23 et la fuite rénale de phosphate ne sont pas identifiés par le score seul.','p82-xlh-mecanisme-bilan')],
 [('Un enfant peut-il reprendre Dafalgan selon l’intervalle adulte de quatre heures ?','aips82-dafalgan-5'),('Non ; l’AIPS donne un intervalle pédiatrique de six à huit heures et des plafonds dépendant du poids et de la forme.','aips82-dafalgan-5'),('Le plafond pédiatrique de 75 mg/kg/jour ne permet pas de dépasser les plafonds plus bas du tableau correspondant ; le cumul de médicaments contenant du paracétamol doit aussi être recherché.','aips82-dafalgan-5')],
 [('Une mère allaitante insuffisante rénale peut-elle recevoir du gadolinium au seul motif que l’allaitement peut se poursuivre ?','pa82-esur-mere-renale'),('Non ; ESUR indique de ne pas administrer de gadolinium chez une mère enceinte ou allaitante avec insuffisance rénale.','pa82-esur-mere-renale'),('Cette situation particulière prime sur la règle générale de poursuite de l’allaitement après un macrocyclique.',['pa82-esur-mere-renale','pa82-esur-allaitement'])],
 [('Faut-il attendre la ponction d’une articulation suspecte d’infection malgré un sepsis ?','pa82-arthrite-ponction'),('Non ; le sepsis fait exception à la séquence prélèvement avant antibiothérapie empirique.','pa82-arthrite-ponction'),('Le risque systémique impose une prise en charge immédiate ; hors sepsis, prélever avant antibiotique améliore l’identification bactérienne.',['pa82-arthrite-ponction','pa82-arthrite-suspecte'])]
])
p.sauver()
